import numpy as np
def comps(g, allow_diag=False):
    r,c=len(g),len(g[0])
    lab=np.full((r,c),-1)
    def nb(i,j,d):
        for di in (-1,0,1):
            for dj in (-1,0,1):
                if d and di==0 and dj==0: continue
                y,x=i+di,j+dj
                if 0<=y<r and 0<=x<c: yield y,x
    id_=0
    for i in range(r):
        for j in range(c):
            if g[i][j]==0 and lab[i][j]==-1:
                q=[(i,j)];lab[i][j]=id_;s=set()
                while q:
                    y,x=q.pop();s.add((y,x))
                    for yy,xx in nb(y,x,int(not allow_diag)):
                        if 0<=yy<r and 0<=xx<c and lab[yy][xx]==-1 and g[yy][xx]==0:
                            lab[yy][xx]=id_;q.append((yy,xx))
                yield id_,s
    return lab
